'use client'

import * as React from 'react'
import { DropdownMenu, Popover } from 'radix-ui'
import { ArrowUp, Attachment as AttachmentIcon, Check, Globe, Microphone, NavArrowDown, Page, Plus, Search, Xmark } from 'iconoir-react'
import { cn } from '@/lib/utils'
import { Button } from '@/registry/satin/ui/button'
import { KbdArrowDown, KbdArrowUp, KbdHint, KbdReturn } from '@/registry/satin/ui/kbd'
import { defaultLabels, useSatinLabels, type SatinLabelSet } from '@/registry/satin/ui/labels'

/**
 * PromptBar, 1:1 with the uiKit `PromptBar` set (3158:21803), its input row
 * `_prompterInteractions` (3157:23767), `_dictationButton` (3156:40589), the `Attachment` chips
 * (3141:20409) and the two menus `_dropdowns/addToConversation` (3157:23548) and
 * `dropdowns/models`.
 *
 * The bar: bg/field, 1px border/default, shadow/xs, 8px padding, rows 8px apart. shape
 * default = radius 12 with Default buttons; pill = radius-full on one line, radius 20 once
 * attachments or a second line of text add height, with Rounded buttons. The input row is
 * add (+), the field (14/21, placeholder text/subtle), then 4px apart the model select, dictation
 * and send — all 28px DS buttons. Once the text needs a second line the bar expands: the field
 * takes its own row, with + and the model below on the left and dictation and send on the right. state inactive: border/default and send disabled; active (the
 * field focused, or text to send): border/strong and send enabled.
 *
 * Menus open 8px above: + opens addToConversation across the full width of the bar, the model
 * select opens the models list (241px, right-aligned); the trigger shows its pressed fill.
 * Dictation toggles to the primary button with a three-bar wave that moves while it records.
 * Enter sends, Shift+Enter adds a line.
 */
export interface PromptBarModel {
  value: string
  label: string
  /** 20px in the menu, 16px on the select. */
  icon?: React.ReactNode
}

export interface PromptBarAction {
  id: string
  label: string
  description?: string
  /** 16px icon. */
  icon?: React.ReactNode
  /** Without it, the `upload` action opens the file picker and adds the files as attachments. */
  onSelect?: () => void
}

export interface PromptBarProps extends Omit<React.ComponentProps<'form'>, 'onSubmit'> {
  shape?: 'pill' | 'default'
  /** The text. Pass it with onValueChange to control it. */
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  /** Defaults to the `writeMessage` label. */
  placeholder?: string
  /** Files shown as chips above the field; people can remove them before sending. */
  attachments?: File[]
  onAttachmentsChange?: (files: File[]) => void
  /** The selected model's value (or its label, when there is no `models` list). */
  model?: string
  /** The models menu. Without it the select shows `model` and opens nothing. */
  models?: PromptBarModel[]
  onModelChange?: (value: string) => void
  /** Icon on the select when `models` doesn't give one. */
  modelIcon?: React.ReactNode
  /** Rows of the + menu. Defaults to Upload a file and Web search, in the `uploadFile` and `webSearch` labels. */
  actions?: PromptBarAction[]
  /** The + at the end of the menu's search row. */
  onAddAgent?: () => void
  onDictationChange?: (recording: boolean) => void
  disabled?: boolean
  onSubmit?: (value: string, attachments: File[]) => void
}

/** Upload a file and Web search, in the words of `labels`. */
const actionsIn = (labels: SatinLabelSet): PromptBarAction[] => [
  { id: 'upload', label: labels.uploadFile, description: labels.uploadFileDescription, icon: <AttachmentIcon /> },
  { id: 'web', label: labels.webSearch, description: labels.webSearchDescription, icon: <Globe /> },
]

/**
 * Upload a file and Web search: spread them into `actions` to add your own rows after them.
 * These are the English rows; left without `actions`, PromptBar shows them in the SatinLabels words.
 */
export const defaultActions: PromptBarAction[] = actionsIn(defaultLabels)

/** Menu card: bg/popover, border/subtle, radius 12, shadow/sm. */
const menuCard = [
  'sa:overflow-clip sa:rounded-xl sa:border sa:border-border-subtle sa:bg-bg-popover',
  'sa:[box-shadow:0_1px_3px_0_var(--sa-effect-shadow-sm),0_1px_2px_-1px_var(--sa-effect-shadow-sm)]',
  'sa:origin-(--radix-popper-transform-origin) sa:data-[state=open]:animate-[satin-enter_var(--sa-duration-base)_var(--sa-ease-out)]',
  'sa:focus-visible:outline-none',
]

export function PromptBar({
  shape = 'pill',
  value: valueProp,
  defaultValue = '',
  onValueChange,
  placeholder,
  attachments: attachmentsProp,
  onAttachmentsChange,
  model: modelProp,
  models,
  onModelChange,
  modelIcon,
  actions: actionsProp,
  onAddAgent,
  onDictationChange,
  disabled = false,
  onSubmit,
  className,
  ...props
}: PromptBarProps) {
  const labels = useSatinLabels()
  const actions = React.useMemo(() => actionsProp ?? actionsIn(labels), [actionsProp, labels])
  const [innerValue, setInnerValue] = React.useState(defaultValue)
  const value = valueProp ?? innerValue
  const [files, setFiles] = React.useState<File[]>(attachmentsProp ?? [])
  React.useEffect(() => setFiles(attachmentsProp ?? []), [attachmentsProp])
  const [model, setModel] = React.useState(modelProp ?? models?.[0]?.value ?? '')
  React.useEffect(() => {
    if (modelProp != null) setModel(modelProp)
  }, [modelProp])
  const [addOpen, setAddOpen] = React.useState(false)
  const [recording, setRecording] = React.useState(false)
  // Expanded: the text has needed a second line. It stays expanded until the field is empty,
  // so the layout doesn't flip back when the wider field fits the text on one line again.
  const [expanded, setExpanded] = React.useState(false)
  const textareaRef = React.useRef<HTMLTextAreaElement>(null)
  const fileRef = React.useRef<HTMLInputElement>(null)

  const setValue = (next: string) => {
    setInnerValue(next)
    onValueChange?.(next)
  }
  const setAttachments = (next: File[]) => {
    setFiles(next)
    onAttachmentsChange?.(next)
  }

  const canSend = !disabled && (value.trim().length > 0 || files.length > 0)
  const current = models?.find((m) => m.value === model)
  const pill = shape === 'pill'
  const btnShape = pill ? 'rounded' : 'default'

  // The field grows with the text, up to six lines; a pill turns into radius 20 once it wraps.
  React.useLayoutEffect(() => {
    const el = textareaRef.current
    if (!el) return
    el.style.height = '0px'
    const h = Math.min(el.scrollHeight, 6 * 21 + 7)
    el.style.height = `${h}px`
    if (value.length === 0) setExpanded(false)
    else if (h > 28) setExpanded(true)
  }, [value, expanded])

  const submit = () => {
    if (!canSend) return
    onSubmit?.(value.trim(), files)
    setValue('')
    setAttachments([])
  }

  const runAction = (action: PromptBarAction) => {
    setAddOpen(false)
    if (action.onSelect) action.onSelect()
    else if (action.id === 'upload') fileRef.current?.click()
  }

  return (
    <Popover.Root open={addOpen} onOpenChange={setAddOpen}>
      <Popover.Anchor asChild>
        <form
          data-slot="prompt-bar"
          data-shape={shape}
          data-filled={value.length > 0 || undefined}
          aria-disabled={disabled || undefined}
          onSubmit={(e) => {
            e.preventDefault()
            submit()
          }}
          className={cn(
            'sa:flex sa:w-full sa:flex-col sa:gap-2 sa:border sa:border-border-default sa:bg-bg-field sa:p-2 sa:[box-shadow:0_1px_2px_0_var(--sa-effect-shadow-xs)]',
            'sa:transition-[border-color,border-radius] sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)',
            'sa:data-filled:border-border-strong',
            // Focus: a 2px border/focus edge, as on every field.
            'sa:has-[textarea:focus-visible]:border-border-focus sa:has-[textarea:focus-visible]:[box-shadow:0_0_0_1px_var(--sa-border-focus)]',
            pill ? (files.length > 0 || expanded ? 'sa:rounded-3xl' : 'sa:rounded-pill') : 'sa:rounded-xl',
            disabled && 'sa:opacity-50',
            className,
          )}
          {...props}
        >
          <input
            ref={fileRef}
            type="file"
            multiple
            hidden
            onChange={(e) => {
              const picked = Array.from(e.target.files ?? [])
              if (picked.length) setAttachments([...files, ...picked])
              e.target.value = ''
            }}
          />

          {files.length > 0 && (
            <ul aria-label={labels.attachments} className="sa:flex sa:flex-wrap sa:gap-1 sa:pb-1">
              {files.map((file, i) => (
                <li key={`${file.name}-${i}`}>
                  <AttachmentChip
                    file={file}
                    rounded={pill}
                    disabled={disabled}
                    onRemove={() => setAttachments(files.filter((_, j) => j !== i))}
                  />
                </li>
              ))}
            </ul>
          )}

          {/* One line: + | field | model, dictation, send. Expanded: the field on its own row over
              + and the model on the left, dictation and send on the right. */}
          <div className={cn('sa:flex sa:flex-wrap sa:items-end sa:gap-x-2 sa:gap-y-2', expanded && 'sa:items-center')}>
            <Popover.Trigger asChild>
              <Button
                variant="tertiary"
                size="md"
                shape={btnShape}
                iconOnly
                disabled={disabled}
                aria-label={labels.addToConversation}
                className="sa:data-[state=open]:bg-bg-pressed"
              >
                <Plus />
              </Button>
            </Popover.Trigger>

            <textarea
              ref={textareaRef}
              rows={1}
              value={value}
              disabled={disabled}
              placeholder={placeholder ?? labels.writeMessage}
              aria-label={labels.message}
              onChange={(e) => setValue(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
                  e.preventDefault()
                  submit()
                }
              }}
              className={cn(
                'sa:block sa:h-7 sa:min-w-0 sa:flex-1 sa:resize-none sa:bg-transparent sa:py-[3.5px] sa:text-base sa:leading-[21px] sa:text-text-default',
                expanded && 'sa:order-first sa:basis-full sa:px-1',
                'sa:outline-none sa:placeholder:text-text-muted sa:focus-visible:ring-0 sa:disabled:cursor-not-allowed',
              )}
            />

            <div className={cn('sa:flex sa:shrink-0 sa:items-center sa:gap-1', expanded && 'sa:contents')}>
              <ModelSelect
                models={models}
                model={model}
                label={current?.label ?? model}
                icon={current?.icon ?? modelIcon}
                shape={btnShape}
                disabled={disabled}
                onChange={(next) => {
                  setModel(next)
                  onModelChange?.(next)
                }}
              />
              {expanded && <span aria-hidden className="sa:flex-1" />}
              <DictationButton
                shape={btnShape}
                recording={recording}
                disabled={disabled}
                onToggle={() => {
                  setRecording(!recording)
                  onDictationChange?.(!recording)
                }}
              />
              <Button type="submit" variant="primary" size="md" shape={btnShape} iconOnly aria-label={labels.send} disabled={!canSend}>
                <ArrowUp />
              </Button>
            </div>
          </div>
        </form>
      </Popover.Anchor>

      <Popover.Portal>
        <Popover.Content
          side="top"
          align="start"
          sideOffset={8}
          avoidCollisions={false}
          aria-label={labels.addToConversation}
          className={cn(menuCard, 'sa:z-50 sa:flex sa:w-(--radix-popper-anchor-width) sa:flex-col')}
        >
          <AddMenu actions={actions} onAction={runAction} onAddAgent={onAddAgent} />
        </Popover.Content>
      </Popover.Portal>
    </Popover.Root>
  )
}

/* ---------- add to conversation ---------- */

function AddMenu({
  actions,
  onAction,
  onAddAgent,
}: {
  actions: PromptBarAction[]
  onAction: (a: PromptBarAction) => void
  onAddAgent?: () => void
}) {
  const labels = useSatinLabels()
  const [query, setQuery] = React.useState('')
  const [active, setActive] = React.useState(0)
  // The highlight shows the focus ring only when the arrows put it there (see menuItemClass).
  const [viaKeys, setViaKeys] = React.useState(false)
  const id = React.useId()
  const q = query.trim().toLowerCase()
  const shown = q
    ? actions.filter((a) => `${a.label} ${a.description ?? ''}`.toLowerCase().includes(q))
    : actions
  const index = Math.min(active, Math.max(shown.length - 1, 0))

  return (
    <>
      <div className="sa:flex sa:items-center sa:gap-1 sa:pe-1.5">
        <label className="sa:flex sa:flex-1 sa:items-center sa:gap-2 sa:px-3 sa:py-1.5">
          <Search aria-hidden className="sa:size-icon-size sa:shrink-0 sa:text-text-muted sa:[stroke-width:1.875]" />
          <input
            role="combobox"
            aria-expanded
            aria-controls={`${id}-list`}
            aria-activedescendant={shown.length ? `${id}-${index}` : undefined}
            aria-label={labels.searchAgentsAndTools}
            placeholder={labels.searchAgentsAndTools}
            value={query}
            onChange={(e) => {
              setQuery(e.target.value)
              setActive(0)
            }}
            onKeyDown={(e) => {
              if (e.key === 'ArrowDown') {
                e.preventDefault()
                setViaKeys(true)
                setActive((index + 1) % Math.max(shown.length, 1))
              } else if (e.key === 'ArrowUp') {
                e.preventDefault()
                setViaKeys(true)
                setActive((index - 1 + shown.length) % Math.max(shown.length, 1))
              } else if (e.key === 'Enter' && shown[index]) {
                e.preventDefault()
                onAction(shown[index])
              }
            }}
            className="sa:min-w-0 sa:flex-1 sa:bg-transparent sa:text-sm sa:text-text-default sa:outline-none sa:placeholder:text-text-muted sa:focus-visible:ring-0"
          />
        </label>
        <Button variant="tertiary" size="xs" iconOnly aria-label={labels.addAgent} onClick={onAddAgent}>
          <Plus />
        </Button>
      </div>
      <div aria-hidden className="sa:h-px sa:bg-border-subtle" />
      <div id={`${id}-list`} role="listbox" aria-label={labels.agentsAndTools} className="sa:flex sa:flex-col sa:p-1">
        {shown.map((a, i) => (
          <div
            key={a.id}
            id={`${id}-${i}`}
            role="option"
            aria-selected={i === index}
            data-keyboard={i === index && viaKeys ? '' : undefined}
            onPointerMove={() => {
              setViaKeys(false)
              setActive(i)
            }}
            onMouseDown={(e) => e.preventDefault()}
            onClick={() => onAction(a)}
            className={cn(
              'sa:flex sa:min-h-8 sa:items-center sa:gap-2 sa:rounded-lg sa:px-2 sa:py-1.5',
              'sa:data-[keyboard]:[box-shadow:inset_0_0_0_2px_var(--sa-action-focus-ring)]',
              'sa:[&>svg]:size-icon-size sa:[&>svg]:shrink-0 sa:[&>svg]:text-text-muted sa:[&>svg]:[stroke-width:1.875]',
              i === index && 'sa:bg-bg-hover',
            )}
          >
            {a.icon}
            <span className="sa:flex sa:min-w-0 sa:flex-1 sa:items-baseline sa:gap-3">
              <span className="sa:shrink-0 sa:text-sm sa:leading-[13px] sa:font-medium sa:whitespace-nowrap sa:text-text-default">{a.label}</span>
              {a.description && <span className="sa:min-w-0 sa:flex-1 sa:truncate sa:text-sm sa:text-text-muted">{a.description}</span>}
            </span>
          </div>
        ))}
        {shown.length === 0 && <p className="sa:px-2 sa:py-1.5 sa:text-sm sa:text-text-muted">{labels.noMatches}</p>}
      </div>
      <ShortcutHints />
    </>
  )
}

/* ---------- models ---------- */

function ModelSelect({
  models,
  model,
  label,
  icon,
  shape,
  disabled,
  onChange,
}: {
  models?: PromptBarModel[]
  model: string
  label: string
  icon?: React.ReactNode
  shape: 'rounded' | 'default'
  disabled: boolean
  onChange: (value: string) => void
}) {
  const labels = useSatinLabels()
  if (!label) return null
  const trigger = (
    <Button
      variant="tertiary"
      size="md"
      shape={shape}
      disabled={disabled}
      className="sa:data-[state=open]:bg-bg-pressed"
    >
      {icon && <span className="sa:flex sa:size-4 sa:shrink-0 sa:items-center sa:justify-center sa:[&>*]:size-4">{icon}</span>}
      <span className="sa:sr-only">{labels.model}: </span>
      {label}
      <NavArrowDown aria-hidden data-chevron />
    </Button>
  )
  if (!models?.length) return trigger

  return (
    <DropdownMenu.Root>
      <DropdownMenu.Trigger asChild>{trigger}</DropdownMenu.Trigger>
      <DropdownMenu.Portal>
        <DropdownMenu.Content
          side="top"
          align="end"
          sideOffset={8}
          avoidCollisions={false}
          className={cn(menuCard, 'sa:z-50 sa:w-[241px]')}
        >
          <DropdownMenu.RadioGroup value={model} onValueChange={onChange} className="sa:flex sa:flex-col sa:p-1">
            {models.map((m) => (
              <DropdownMenu.RadioItem
                key={m.value}
                value={m.value}
                className={cn(
                  'sa:flex sa:min-h-8 sa:cursor-pointer sa:items-center sa:gap-2 sa:rounded-lg sa:px-2 sa:py-1.5 sa:outline-none sa:select-none',
                  'sa:data-highlighted:bg-bg-hover sa:data-[state=checked]:bg-bg-selected',
                  'sa:focus-visible:[box-shadow:inset_0_0_0_2px_var(--sa-action-focus-ring)]',
                )}
              >
                <span className="sa:flex sa:size-5 sa:shrink-0 sa:items-center sa:justify-center sa:[&>*]:size-5">{m.icon}</span>
                <span className="sa:min-w-0 sa:flex-1 sa:truncate sa:text-sm sa:leading-[13px] sa:font-medium sa:text-text-default">{m.label}</span>
                <DropdownMenu.ItemIndicator>
                  <Check aria-hidden className="sa:size-icon-size sa:text-status-green-fg sa:[stroke-width:1.875]" />
                </DropdownMenu.ItemIndicator>
              </DropdownMenu.RadioItem>
            ))}
          </DropdownMenu.RadioGroup>
          <ShortcutHints />
        </DropdownMenu.Content>
      </DropdownMenu.Portal>
    </DropdownMenu.Root>
  )
}

/**
 * The footer both menus share: ↑ ↓ Navigate, ↵ Select, on the menu's own bg/popover under a
 * border/default rule. Keys are Kbd sm.
 */
function ShortcutHints() {
  const labels = useSatinLabels()
  return (
    <div aria-hidden className="sa:flex sa:items-center sa:gap-3 sa:border-t sa:border-border-default sa:bg-bg-popover sa:px-3 sa:py-1.5">
      <KbdHint keys={[<KbdArrowUp key="up" />, <KbdArrowDown key="down" />]} label={labels.navigate} />
      <KbdHint keys={[<KbdReturn key="return" />]} label={labels.selectItem} />
    </div>
  )
}

/* ---------- dictation ---------- */

function DictationButton({
  shape,
  recording,
  disabled,
  onToggle,
}: {
  shape: 'rounded' | 'default'
  recording: boolean
  disabled: boolean
  onToggle: () => void
}) {
  const labels = useSatinLabels()
  const waveRef = React.useRef<SVGSVGElement>(null)

  // The three bars of the wave breathe out of step while recording (transform only).
  React.useEffect(() => {
    const svg = waveRef.current
    if (!recording || !svg || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return
    const anims = Array.from(svg.querySelectorAll('path')).map((bar, i) =>
      bar.animate([{ transform: 'scaleY(1)' }, { transform: 'scaleY(0.45)' }, { transform: 'scaleY(1)' }], {
        duration: 900,
        delay: i * 150,
        iterations: Infinity,
        easing: 'ease-in-out',
      }),
    )
    return () => anims.forEach((a) => a.cancel())
  }, [recording])

  return (
    <Button
      variant={recording ? 'primary' : 'tertiary'}
      size="md"
      shape={shape}
      iconOnly
      disabled={disabled}
      aria-label={recording ? labels.stopDictation : labels.dictate}
      aria-pressed={recording}
      onClick={onToggle}
    >
      {recording ? (
        <svg ref={waveRef} viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeLinecap="round" aria-hidden>
          <path d="M4.66667 6.33333V9.66633" strokeWidth="1.25" style={{ transformBox: 'fill-box', transformOrigin: 'center' }} />
          <path d="M8 3.66667V12.3337" strokeWidth="1.25" style={{ transformBox: 'fill-box', transformOrigin: 'center' }} />
          <path d="M11.3333 5.33333V10.6663" strokeWidth="1.25" style={{ transformBox: 'fill-box', transformOrigin: 'center' }} />
        </svg>
      ) : (
        <Microphone />
      )}
    </Button>
  )
}

/* ---------- attachments ---------- */

function AttachmentChip({
  file,
  rounded,
  disabled,
  onRemove,
}: {
  file: File
  rounded: boolean
  disabled: boolean
  onRemove: () => void
}) {
  const labels = useSatinLabels()
  return (
    <span
      data-slot="attachment"
      className={cn(
        'sa:flex sa:h-control-height sa:items-center sa:gap-1.5 sa:border sa:border-border-default sa:bg-bg-popover sa:ps-2 sa:pe-0.5',
        'sa:[filter:drop-shadow(0_1px_1px_var(--sa-effect-shadow-xs))]',
        'sa:transition-[background-color,border-color] sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)',
        'sa:hover:border-border-strong sa:hover:bg-bg-canvas sa:active:border-border-strong sa:active:bg-bg-muted',
        rounded ? 'sa:rounded-pill' : 'sa:rounded-md',
      )}
    >
      <FileIcon name={file.name} />
      <span className="sa:max-w-[200px] sa:truncate sa:text-sm sa:font-medium sa:text-text-default">{file.name}</span>
      <Button
        variant="tertiary"
        size="xs"
        shape="rounded"
        iconOnly
        disabled={disabled}
        aria-label={labels.removeItem(file.name)}
        onClick={onRemove}
      >
        <Xmark className="sa:![stroke-width:1.64]" />
      </Button>
    </span>
  )
}

/* File type icons keep their own colours (library primitives), 1:1 with Icon=filePdf/Doc/Xlsx. */
const PAGE =
  'M2.66673 3.33327C2.66673 2.22873 3.56218 1.33327 4.66673 1.33327H5.72127C5.86673 1.33327 6.00339 1.36788 6.13127 1.43709L13.1416 5.22945C13.2695 5.29867 13.3335 5.406 13.3335 5.55145V12.6665C13.3335 13.7711 12.438 14.6665 11.3335 14.6665H4.66673C3.56218 14.6665 2.66673 13.7711 2.66673 12.6665V3.33327Z'
const FOLD = 'M5.93945 1.33327L13.3335 5.33327L10.8985 6.92509C10.2898 7.32303 9.78648 7.21764 9.38855 6.60891L5.93945 1.33327Z'
